-- Tab Summary: cost per komponen per BA per bulan (ribu Rp), aktual (a*) dan budget (b*). Hasil -> work/r_sumcost.json (list baris: ba, bulan, 7 aktual, 7 budget)
-- Urutan komponen: Rawat, Infra, Pupuk, Panen, Transport, Umum(+Sewa AMP), Penyusutan. PMY = 2131 + 2122, afd B dikeluarkan. Ganti batas BULAN sesuai bulan laporan.
SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, TO_CHAR(DATE_TRUNC('month',BULAN),'YYYY-MM') m,
 ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PERAWATAN',RP_ACTUAL,0))/1000) aup, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA INFRA',RP_ACTUAL,0))/1000) ainf, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PEMUPUKAN',RP_ACTUAL,0))/1000) afert, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PANEN',RP_ACTUAL,0))/1000) aharv, ROUND(SUM(IFF(GROUP_LEVEL='TRANSPORT PANEN',RP_ACTUAL,0))/1000) atrans, ROUND(SUM(IFF(GROUP_LEVEL IN ('BIAYA UMUM','COST SEWA AMP'),RP_ACTUAL,0))/1000) aovh, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PENYUSUTAN',RP_ACTUAL,0))/1000) adepr,
 ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PERAWATAN',RP_BUDGET,0))/1000) bup, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA INFRA',RP_BUDGET,0))/1000) binf, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PEMUPUKAN',RP_BUDGET,0))/1000) bfert, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PANEN',RP_BUDGET,0))/1000) bharv, ROUND(SUM(IFF(GROUP_LEVEL='TRANSPORT PANEN',RP_BUDGET,0))/1000) btrans, ROUND(SUM(IFF(GROUP_LEVEL IN ('BIAYA UMUM','COST SEWA AMP'),RP_BUDGET,0))/1000) bovh, ROUND(SUM(IFF(GROUP_LEVEL='BIAYA PENYUSUTAN',RP_BUDGET,0))/1000) bdepr
FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST
WHERE KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01'
GROUP BY 1,2 ORDER BY 1,2;
